import React from 'react';

const Servicios = () => (
  <div className="container">
    <h2>Servicios</h2>
    <ul>
      <li>Declaración de rentas</li>
      <li>Asesoría contable</li>
      <li>Auditoría financiera</li>
      <li>Gestión tributaria</li>
      <li>Consultoría empresarial</li>
      <li>Outsourcing contable</li>
    </ul>
  </div>
);

export default Servicios;
